import argparse,gzip,hashlib,json,subprocess
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--output',required=True);p.add_argument('--legacy',action='store_true');args=p.parse_args()
ref=json.loads(gzip.decompress(Path('docs/heuristic-dfg-input-reference.json.gz').read_bytes()));rows=ref['observations']
if args.legacy:
 legacy=json.loads(gzip.decompress(Path('docs/heuristic-dfg-metadata-reference.json.gz').read_bytes()));rows=[]
 for part in legacy['parts']:
  for i,r in enumerate(part['observations']):
   row={'name':part['name']+'_'+str(i),'dfg':[['A','B',1]],'activities':r.get('activities_input',r.get('activities')),'occurrences':r.get('occurrences_input') if part['name']=='metadata' else {'A':1,'B':1},'parameters':{'dependency_thresh':r.get('dependency_threshold',r.get('dependency')),'dfg_pre_cleaning_noise_thresh':r.get('noise',.05)}}
   row['expected_error' if 'error' in r else 'expected']=r.get('error',r.get('expected'));rows.append(row)
q=lambda s:json.dumps(s,ensure_ascii=False)
def names(xs):return str(len(xs))+' '+ ' '.join(q(x) for x in xs)
def counts(xs):return str(len(xs))+' '+' '.join(q(k)+' '+str(v) for k,v in xs.items())
def boundary(x):return '0' if x is None else ('1 '+counts(x) if isinstance(x,dict) else '2 '+names(x))
lines=[str(len(rows))]
for r in rows:
 a=r['activities'];c=r['occurrences'];p=r['parameters']
 lines.append(' '.join([q(r['name']),str(len(r['dfg'])),' '.join(q(a)+' '+q(b)+' '+str(v) for a,b,v in r['dfg']), str(len(r.get('window_two_dfg',[]))), ' '.join(q(a)+' '+q(b)+' '+str(v) for a,b,v in r.get('window_two_dfg',[])), str(len(r.get('frequency_triples',[]))), ' '.join(q(a)+' '+q(b)+' '+q(c)+' '+str(v) for a,b,c,v in r.get('frequency_triples',[])), '0' if a is None else '1 '+names(a), '0' if c is None else '1 '+counts(c),boundary(r.get('start')),boundary(r.get('end')),str(p.get('dependency_thresh',.5)),str(p.get('dfg_pre_cleaning_noise_thresh',.05)),str(p.get('min_dfg_occurrences',1)),str(p.get('min_act_count',1))]))
inputs=Path('build/heuristic-dfg-input-probe.txt');inputs.write_text('\n'.join(lines)+'\n',encoding='utf-8')
exe=Path('build/heuristic-dfg-input-probe-build/Release/heuristic_dfg_input_probe.exe');core=Path('build/petri-comparison-checkpoint-build/Release/minera_core.lib');h=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();hashes={'probe_executable_sha256':h(exe),'core_library_sha256':h(core)}
proc=subprocess.run([str(exe),str(inputs)],capture_output=True,text=True,timeout=60,check=True);payloads=json.loads(proc.stdout);assert len(payloads)==len(rows)
checks=[]
for r,payload in zip(rows,payloads):
 actual=payload
 if 'heuristics_net'in payload:
  n=payload['heuristics_net'];registry=n['activities'] if n['activity_ids_are_local'] else [a['name'] for a in payload['activities']]
  metadata=n.get('metadata')
  if metadata:
   actual={'activities':metadata['activities'],'occurrences':metadata['activities_occurrences'],'start_activities':metadata['start_activities'],'end_activities':metadata['end_activities']}
  else:
   stats=n['activity_statistics'];actual={'activities':n['activities'],'occurrences':{registry[s['activity']]:s['occurrences'] for s in stats}}
   for side in ['start','end']:
    key=side+'_occurrences';actual[side+'_activities']=[{registry[s['activity']]:s[key] for s in stats if s[key]}] if isinstance(r.get(side),dict) else [[registry[s['activity']] for s in stats if s[key]]]
  actual['nodes']=sorted(registry[i] for i in n['active_activities'])
  edges=[[registry[e['source']],registry[e['target']],e['dependency'],e['frequency'],e['representation']] for e in n['edges']]
  actual['edges']=sorted(edges,key=lambda e:json.dumps(e,sort_keys=True));actual['dependency_matrix']={}
  for d in n['dependency_measures']:actual['dependency_matrix'].setdefault(registry[d['source']],{})[registry[d['target']]]=d['value']
  actual['loop_length_two']=sorted([[registry[x['source']],registry[x['target']],x['frequency']] for x in n['loop_length_two']])
  if 'window_two_dfg'in r:actual['window_two_dfg']=sorted([[[registry[x['source']],registry[x['target']]],x['count']] for x in n['window_two_dfg']])
  if 'frequency_triples'in r:actual['frequency_triples']=sorted([[[registry[x['first']],registry[x['middle']],registry[x['last']]],x['count']] for x in n['frequency_triples']])
 matched=bool(actual.get('rejected')) if 'expected_error'in r else all(actual.get(k)==v for k,v in r['expected'].items())
 checks.append({'name':r['name'],'expected':r.get('expected'),'expected_error':r.get('expected_error'),'actual':actual,'matched':matched})
assert hashes=={'probe_executable_sha256':h(exe),'core_library_sha256':h(core)}
Path(args.output).write_text(json.dumps(dict(hashes,checks=checks,probe_source=Path('build/heuristic-dfg-input-probe-source/main.cpp').read_text(),probe_metadata_input_enabled='HAS_DFG_METADATA:BOOL=ON' in Path('build/heuristic-dfg-input-probe-build/CMakeCache.txt').read_text(),input_sha256=h(inputs)),indent=2)+'\n')
print(sum(c['matched'] for c in checks),'/',len(checks));print([c['name'] for c in checks if not c['matched']][:25])

eventlog_checker_script:
import argparse,gzip,hashlib,json,subprocess
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--output',required=True);p.add_argument('--start-index',type=int,default=0);args=p.parse_args()
ref=json.loads(gzip.decompress(Path('docs/heuristic-eventlog-metadata-reference.json.gz').read_bytes()));exe=Path('build/petri-comparison-checkpoint-build/Release/minera_export.exe');before=hashlib.sha256(exe.read_bytes()).hexdigest();checks=[]
flags={'dependency_thresh':'--dependency-threshold','and_measure_thresh':'--and-threshold','min_act_count':'--heuristic-min-activity-count','min_dfg_occurrences':'--min-edge-frequency','dfg_pre_cleaning_noise_thresh':'--heuristic-dfg-pre-cleaning-noise-threshold','loop_length_two_thresh':'--heuristic-loop-length-two-threshold'}
for i,r in enumerate(ref['observations'][args.start_index:],start=args.start_index):
 x=Path(f'build/heuristic-eventlog-metadata-{i}.xes');x.write_text(r['xes']);out=x.with_suffix('.json')
 cmd=[str(exe),str(x),'--heuristic-variant',r['variant'].lower(),'--heuristic-decoration',r['decoration'],'--heuristic-performance-aggregation',r['aggregation'],'-o',str(out)]
 if 'pm4py:param:start_timestamp_key' in r['parameters']: cmd+=['--heuristic-start-timestamp-attribute',r['parameters']['pm4py:param:start_timestamp_key']]
 for key,flag in flags.items():
  if key in r['parameters']: cmd += [flag,str(r['parameters'][key])]
 row={'name':r['name'],'expected':r.get('expected'),'expected_error':r.get('expected_error')}
 try:
  proc=subprocess.run(cmd,capture_output=True,text=True,timeout=30);row.update(exit_code=proc.returncode,stderr=proc.stderr)
  if proc.returncode==0:
   payload=json.loads(out.read_text());net=payload['heuristics_net'];names=net['activities'] if net['activity_ids_are_local'] else [a['name'] for a in payload['activities']]
   actual=net.get('metadata')
   row['actual']=actual
  row['matched']=proc.returncode!=0 if 'expected_error' in r else row.get('actual')==r['expected']
 except subprocess.TimeoutExpired: row.update(timeout=True,matched=False)
 checks.append(row)
 if (i+1)%108==0: print(i+1,'checked',flush=True)
after=hashlib.sha256(exe.read_bytes()).hexdigest();assert before==after
Path(args.output).write_text(json.dumps({'checks':checks,'native_executable_sha256':after},indent=2)+'\n',encoding='utf-8')
print(sum(r['matched'] for r in checks),'/',len(checks));print([r['name'] for r in checks if not r['matched']][:25])
